		public CusUSClassificationLookups Lookups
		{
			get
			{
				if (fLookups == null || !IsLookupsCachedInBase)
				{
					fLookups = GetNewLookups();
				}

				return fLookups;
			}
		}

		protected virtual CusUSClassificationLookups GetNewLookups()
		{
			return new CusUSClassificationLookups(this);
		}

		CusUSClassificationLookups fLookups;

